fn prime_num(n: u64) -> bool {
    // Handle small cases
    if n < 2 {
        return false;
    }
    
    // Check for even numbers
    if n == 2 {
        return true;
    }
    if n % 2 == 0 {
        return false;
    }
    
    // Only check odd divisors up to sqrt(n)
    let limit = (n as f64).sqrt() as u64;
    for i in (3..=limit).step_by(2) {
        if n % i == 0 {
            return false;
        }
    }
    
    true
}